const row = $input.first()?.json ?? {};   // empty result => every check fails, loudly

const CHECKS = [
  { name: 'row_count',         expected: 16598 },
  { name: 'null_year',         expected: 271 },
  { name: 'null_publisher',    expected: 58 },
  { name: 'null_required',     expected: 0 },
  { name: 'sales_mismatch',    expected: 0 },
  { name: 'negative_sales',    expected: 0 },
  { name: 'dup_name_platform', expected: 5 },
  { name: 'genres',            expected: 12 },
  { name: 'platforms',         expected: 31 },
  { name: 'min_year',          expected: 1980 },
  { name: 'max_year',          expected: 2020 },
  { name: 'global_total',      expected: 8920.44, tol: 0.005 },
  { name: 'long_rows',         expected: 66392 },
];

const failures = [];
for (const c of CHECKS) {
  const raw = row[c.name];
  const actual = Number(raw);
  const tol = c.tol ?? 0;
  if (raw === undefined || raw === null || Number.isNaN(actual) || Math.abs(actual - c.expected) > tol) {
    failures.push(`${c.name}: expected ${c.expected}, got ${raw}`);
  }
}

return [{
  json: {
    ok: failures.length === 0,
    failures,
    message: `Data quality FAILED (${failures.length} checks)\n` + failures.join('\n'),
  },
}];
